var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var orders = new List<Order> { new(1042, "Blue mug", "Open"), new(1043, "Red mug", "Shipped") };

app.MapGet("/orders", () => Results.Content(
    "<h1>Orders</h1><table><tr><th>Order</th><th>Status</th><th></th></tr>" +
    string.Concat(orders.Select(o => $"<tr><td>{o.Id}</td><td>{o.Status}</td><td><form method='post' action='/orders/{o.Id}/cancel'><button>Cancel order {o.Id}</button></form></td></tr>")) +
    "</table>", "text/html"));

app.MapPost("/orders/{id:int}/cancel", (int id) =>
{
    var i = orders.FindIndex(o => o.Id == id);
    if (i < 0) return Results.NotFound();
    if (orders[i].Status == "Shipped") return Results.Content("<p role='alert'>A shipped order cannot be cancelled.</p>", "text/html");
    orders[i] = orders[i] with { Status = "Cancelled" };
    return Results.Redirect("/orders");
});

app.Run();

public record Order(int Id, string Product, string Status);

