using Xunit;
using Xunit.Abstractions;

[assembly: CollectionBehavior(DisableTestParallelization = true)]

namespace Billing.Tests;

public class InvoiceTests : IAsyncLifetime
{
    private readonly ITestOutputHelper _output;
    private InvoiceStore _store = null!;

    public InvoiceTests(ITestOutputHelper output) => _output = output;

    public Task InitializeAsync()
    {
        _store = new InvoiceStore();
        return Task.CompletedTask;
    }

    public Task DisposeAsync() => Task.CompletedTask;

    [Theory]
    [InlineData(100, 21, 121)]
    [InlineData(0, 21, 0)]
    public async Task Total_AddsVat(int net, int vatPercent, int expected)
    {
        var invoice = await _store.CreateAsync(net, vatPercent);
        _output.WriteLine($"Invoice {invoice.Id}");
        Assert.Equal(expected, invoice.Total);
    }

    [Fact(Skip = "Needs the mail server")]
    public void Send_MailsTheCustomer()
    {
    }
}

public record Invoice(Guid Id, int Total);

public class InvoiceStore
{
    public Task<Invoice> CreateAsync(int net, int vatPercent, CancellationToken cancellationToken = default)
        => Task.FromResult(new Invoice(Guid.NewGuid(), net + net * vatPercent / 100));
}

