namespace Pricing;

public static class PriceCalculator
{
    /// <summary>Total price, rounded to 2 decimals (away from zero).</summary>
    public static decimal Total(decimal unitPrice, int quantity, decimal discountPercent)
    {
        ArgumentOutOfRangeException.ThrowIfNegative(quantity);
        if (discountPercent is < 0 or > 100) throw new ArgumentOutOfRangeException(nameof(discountPercent));
        var gross = unitPrice * quantity;
        return Math.Round(gross - gross * discountPercent / 100m, 2, MidpointRounding.AwayFromZero);
    }
}
